/**
 * Storage metrics for Prometheus (prom-client).
 *
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 */
import { Counter, Histogram } from 'prom-client';

const SERVICE_NAME = 'ecommerce.ProductService';
const STATUS_SUCCESS = 'success';
const STATUS_ERROR = 'error';

export const storageOperationTotal = new Counter({
  name: 'storage_operation_total',
  help: 'Total number of storage operations',
  labelNames: ['service', 'block', 'provider', 'operation', 'status'],
});

export const storageOperationDurationSeconds = new Histogram({
  name: 'storage_operation_duration_seconds',
  help: 'Duration of storage operations in seconds',
  labelNames: ['service', 'block', 'provider', 'operation'],
  buckets: [0.01, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10, 30],
});

export const storageBytesTotal = new Counter({
  name: 'storage_bytes_total',
  help: 'Total bytes transferred in storage operations',
  labelNames: ['service', 'block', 'provider', 'operation'],
});

/**
 * Run one storage operation (upload / download / delete) and record
 * `storage_operation_total` (with its outcome) and
 * `storage_operation_duration_seconds` for it. Rethrows the failure.
 */
export async function recordStorageOperation<T>(
  block: string,
  provider: string,
  operation: string,
  run: () => Promise<T>,
): Promise<T> {
  const start = process.hrtime.bigint();
  let status = STATUS_SUCCESS;
  try {
    return await run();
  } catch (err) {
    status = STATUS_ERROR;
    throw err;
  } finally {
    const elapsedSeconds = Number(process.hrtime.bigint() - start) / 1e9;
    storageOperationTotal.inc({ service: SERVICE_NAME, block, provider, operation, status });
    storageOperationDurationSeconds.observe(
      { service: SERVICE_NAME, block, provider, operation },
      elapsedSeconds,
    );
  }
}

/** Add the bytes one completed upload or download moved to `storage_bytes_total`. */
export function recordStorageBytes(
  block: string,
  provider: string,
  operation: string,
  bytes: number,
): void {
  storageBytesTotal.inc({ service: SERVICE_NAME, block, provider, operation }, bytes);
}
